import unittest

from hourglass.errors import ProjectError
from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span


def spans(*texts):
    result = []
    for text in texts:
        result.append(parse_span(text))
    return result


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = find_gaps(spans("09:00-12:00", "13:00-17:00"), parse_span("09:00-17:00"))
        self.assertEqual(result, ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        result = find_gaps(spans("10:00-11:00"), parse_span("09:00-12:00"))
        self.assertEqual(
            result, ["gap 09:00-10:00 (60 min)", "gap 11:00-12:00 (60 min)"]
        )

    def test_overlapping_spans_leave_no_gap(self):
        result = find_gaps(spans("09:00-13:00", "12:00-17:00"), parse_span("09:00-17:00"))
        self.assertEqual(result, [])

    def test_nobody_worked(self):
        result = find_gaps([], parse_span("09:00-10:30"))
        self.assertEqual(result, ["gap 09:00-10:30 (90 min)"])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ProjectError):
            find_gaps(spans("08:00-10:00"), parse_span("09:00-17:00"))
        with self.assertRaises(ProjectError):
            find_gaps(spans("16:00-18:00"), parse_span("09:00-17:00"))


if __name__ == "__main__":
    unittest.main()
